import"./hoisted.DKmDz3DY.js";document.addEventListener("DOMContentLoaded",()=>{const o=document.querySelectorAll(".toc-item");if(o.length===0)return;const n=[];if(o.forEach(t=>{const e=t.getAttribute("data-toc-id");if(e){const r=document.getElementById(e);r&&n.push(r)}}),n.length===0)return;const d={root:null,rootMargin:"-80px 0px -60% 0px",threshold:0},s=new IntersectionObserver(t=>{t.forEach(e=>{if(e.isIntersecting){const r=e.target.id;o.forEach(i=>{i.getAttribute("data-toc-id")===r?i.classList.add("text-pink-600","dark:text-pink-300","bg-pink-100/90","dark:bg-purple-900/80","border-l-3","border-pink-500","-ml-[11px]"):i.classList.remove("text-pink-600","dark:text-pink-300","bg-pink-100/90","dark:bg-purple-900/80","border-l-3","border-pink-500","-ml-[11px]")})}})},d);n.forEach(t=>s.observe(t))});
